insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":4939,"materia":"enf","nivel":0,"enunciado":"A esterilização em autoclave utiliza:","opcoes":["Vapor de água sob pressão","Luz ultravioleta comum","Álcool a 70%","Água fervente por 5 minutos"],"explicacao":"É o método mais usado para materiais que resistem ao calor e à umidade."},{"id":4940,"materia":"enf","nivel":0,"enunciado":"A diferença entre esterilização e desinfecção é que a esterilização:","opcoes":["Elimina todas as formas de vida microbiana, inclusive os esporos","Apenas reduz a sujeira visível, sem atingir nenhum microrganismo","Só remove odores","Elimina apenas os vírus"],"explicacao":"A desinfecção não garante a eliminação de todos os esporos."},{"id":4941,"materia":"enf","nivel":0,"enunciado":"Artigos que penetram tecidos estéreis ou o sistema vascular, como instrumentos cirúrgicos, são classificados como:","opcoes":["Críticos e devem ser esterilizados","Não críticos","Semicríticos","Descartáveis sem nenhum cuidado, podendo ser reutilizados diretamente"],"explicacao":"Classificação de Spaulding."},{"id":4942,"materia":"enf","nivel":0,"enunciado":"Artigos que entram em contato apenas com a pele íntegra, como o estetoscópio, são considerados:","opcoes":["Não críticos","Críticos","Semicríticos","Estéreis obrigatoriamente"],"explicacao":"Exigem limpeza e, conforme o caso, desinfecção de baixo nível."},{"id":4943,"materia":"enf","nivel":0,"enunciado":"A vacina contra hepatite B para profissionais de saúde é feita, em geral, em:","opcoes":["3 doses","1 dose","5 doses","Dose anual"],"explicacao":"Recomenda-se verificar a resposta com o exame anti-HBs."},{"id":4944,"materia":"enf","nivel":0,"enunciado":"O reforço da vacina contra difteria e tétano (dT) em adultos é feito a cada:","opcoes":["10 anos","Ano","2 meses","50 anos"],"explicacao":"Em ferimentos graves, o intervalo pode ser menor."},{"id":4945,"materia":"enf","nivel":0,"enunciado":"A vacina gera imunidade:","opcoes":["Ativa, pois o próprio organismo produz anticorpos","Passiva, com anticorpos prontos","Que dura apenas um dia","Sem nenhuma participação do sistema imune, apenas por proteção física da pele"],"explicacao":"O soro dá imunidade passiva e imediata, porém temporária."},{"id":4946,"materia":"enf","nivel":0,"enunciado":"O soro antitetânico ou antiofídico heterólogo é produzido a partir do sangue de:","opcoes":["Cavalos imunizados","Plantas","Bactérias vivas","Doadores humanos de sangue"],"explicacao":"Por isso pode causar reações alérgicas."},{"id":4947,"materia":"enf","nivel":0,"enunciado":"A rigidez de nuca, com febre e dor de cabeça intensa, é sinal clássico de:","opcoes":["Meningite","Gripe comum","Sinusite","Labirintite"],"explicacao":"Exige atendimento imediato."},{"id":4948,"materia":"enf","nivel":0,"enunciado":"As manchas de Koplik, pontos brancos na mucosa da boca, aparecem no:","opcoes":["Sarampo","Tétano","Diabetes","Dengue"],"explicacao":"Surgem antes das manchas vermelhas na pele."},{"id":4949,"materia":"enf","nivel":0,"enunciado":"A hepatite A é transmitida principalmente por:","opcoes":["Via fecal-oral, com água e alimentos contaminados","Transfusão de sangue","Relação sexual apenas, sem outra forma de contágio","Picada de mosquito"],"explicacao":"Saneamento básico e vacina previnem a doença."},{"id":4950,"materia":"enf","nivel":0,"enunciado":"A hepatite B pode ser transmitida por:","opcoes":["Sangue, relação sexual e da mãe para o bebê","Abraço, aperto de mão e uso do mesmo banheiro","Picada de mosquito","Ar, ao falar"],"explicacao":"Há vacina eficaz no calendário do SUS."},{"id":4951,"materia":"enf","nivel":0,"enunciado":"A saturação de oxigênio considerada normal, em pessoa saudável, é em geral:","opcoes":["Igual ou maior que 95%","Entre 50% e 60%","Exatamente 100% em todos","Menor que 80%"],"explicacao":"Medida pelo oxímetro de pulso."},{"id":4952,"materia":"enf","nivel":0,"enunciado":"Para exame de urina tipo 1, a coleta recomendada é a do:","opcoes":["Jato médio, após higiene íntima","Primeiro jato, sem higiene","Urina do vaso sanitário","Final do jato, de qualquer horário"],"explicacao":"Reduz a contaminação da amostra."},{"id":4953,"materia":"enf","nivel":0,"enunciado":"Para pesquisa de tuberculose (baciloscopia), a amostra de escarro de melhor qualidade é a:","opcoes":["Da primeira tosse da manhã, em jejum","Saliva coletada após o almoço","Secreção nasal","Coletada só à noite, após escovar os dentes com pasta"],"explicacao":"Deve vir do fundo do pulmão, não da boca."},{"id":4954,"materia":"enf","nivel":0,"enunciado":"Durante a dieta por sonda enteral, a cabeceira do leito deve ficar elevada a cerca de:","opcoes":["30° a 45°","0°, com o paciente deitado reto","90°, sempre sentado","Abaixo do nível dos pés"],"explicacao":"Reduz o risco de aspiração."},{"id":4955,"materia":"enf","nivel":0,"enunciado":"A via sublingual tem como vantagem:","opcoes":["Absorção rápida, sem passar primeiro pelo fígado","Efeito lento e prolongado, que dura vários dias","Ser a via mais dolorosa","Exigir agulha"],"explicacao":"Ex.: isossorbida em dor no peito, quando prescrita."},{"id":4956,"materia":"enf","nivel":0,"enunciado":"A pediculose é a infestação por:","opcoes":["Piolhos","Pulgas de gato","Carrapatos","Mosquitos"],"explicacao":"Comum em crianças em idade escolar."},{"id":4957,"materia":"enf","nivel":0,"enunciado":"A candidíase (sapinho) é causada por:","opcoes":["Fungo","Vírus","Bactéria","Verme"],"explicacao":"Comum na boca de bebês e em pessoas com baixa imunidade."},{"id":4958,"materia":"enf","nivel":1,"enunciado":"Entre os 'certos' da administração de medicamentos estão:","opcoes":["Paciente certo, medicamento certo, dose certa, via certa e hora certa","Cor certa, cheiro certo e sabor certo","Médico certo, hospital certo, plano de saúde certo, quarto certo e horário de visita certo","Apenas a dose certa"],"explicacao":"Também registro, orientação, forma e resposta certos."},{"id":4959,"materia":"enf","nivel":1,"enunciado":"Artigos que entram em contato com mucosas íntegras, como os de inaloterapia, são:","opcoes":["Semicríticos, exigindo no mínimo desinfecção de alto nível","Não críticos","Críticos, sempre descartáveis após o primeiro uso, sem qualquer reprocessamento","Livres de qualquer cuidado"],"explicacao":"Ex.: máscaras de nebulização e laringoscópios."},{"id":4960,"materia":"enf","nivel":1,"enunciado":"A febre tifoide é causada pela bactéria:","opcoes":["Salmonella Typhi","Vibrio cholerae","Mycobacterium tuberculosis","Treponema pallidum"],"explicacao":"Transmitida por água e alimentos contaminados."},{"id":4961,"materia":"enf","nivel":1,"enunciado":"Na difteria, um achado característico é:","opcoes":["Placas (pseudomembranas) acinzentadas na garganta","Manchas brancas na pele das mãos e dos pés","Coceira nos pés","Dor no joelho"],"explicacao":"Prevenida pela vacina (pentavalente, DTP e dT)."},{"id":4962,"materia":"enf","nivel":1,"enunciado":"O sistema nervoso simpático, em situação de estresse, provoca:","opcoes":["Aumento da frequência cardíaca e dilatação das pupilas","Diminuição da frequência cardíaca e contração das pupilas","Aumento da digestão","Contração das pupilas"],"explicacao":"É a resposta de 'luta ou fuga'."},{"id":4963,"materia":"enf","nivel":1,"enunciado":"A unidade funcional do rim, que filtra o sangue, é o:","opcoes":["Néfron","Neurônio","Alvéolo","Hepatócito"],"explicacao":"Cada rim tem cerca de um milhão de néfrons."},{"id":4964,"materia":"enf","nivel":1,"enunciado":"O sangue rico em oxigênio sai do coração para o corpo pela:","opcoes":["Artéria aorta, a partir do ventrículo esquerdo","Veia cava superior, a partir do átrio direito do coração","Artéria pulmonar","Veia porta"],"explicacao":"A artéria pulmonar leva sangue pobre em oxigênio aos pulmões."},{"id":4965,"materia":"enf","nivel":1,"enunciado":"O ar segue, nos pulmões, do maior para o menor, pelo caminho:","opcoes":["Brônquios, bronquíolos e alvéolos","Alvéolos, brônquios, traqueia e laringe","Bronquíolos, laringe e faringe","Esôfago, estômago e intestino"],"explicacao":"As trocas gasosas acontecem nos alvéolos."},{"id":4966,"materia":"enf","nivel":1,"enunciado":"A malária é causada por um:","opcoes":["Protozoário (Plasmodium), transmitido por mosquito","Vírus transmitido pelo ar em ambientes fechados e úmidos","Fungo do solo","Verme da água"],"explicacao":"Comum na região amazônica."},{"id":4967,"materia":"enf","nivel":1,"enunciado":"A desinfecção de superfícies com matéria orgânica (sangue) deve ser feita:","opcoes":["Retirando primeiro a matéria orgânica com papel e depois aplicando o desinfetante","Apenas passando pano seco","Jogando água e deixando secar naturalmente, sem produto nenhum","Com perfume"],"explicacao":"Segue os protocolos de limpeza do serviço."},{"id":4968,"materia":"enf","nivel":1,"enunciado":"Na lavagem das mãos com água e sabão, o tempo recomendado é de cerca de:","opcoes":["40 a 60 segundos","5 segundos, apenas molhando as mãos","10 minutos","2 segundos"],"explicacao":"Com fricção com álcool, de 20 a 30 segundos."},{"id":4969,"materia":"enf","nivel":1,"enunciado":"O sinal de infecção no local de inserção do cateter venoso inclui:","opcoes":["Vermelhidão, calor, secreção purulenta e dor","Pele fria e pálida","Ausência de qualquer alteração","Coceira leve, sem mudança de cor, temperatura ou secreção no local"],"explicacao":"O cateter deve ser retirado e o fato comunicado."},{"id":4970,"materia":"enf","nivel":1,"enunciado":"A gestante com sífilis deve ser acompanhada após o tratamento com:","opcoes":["VDRL mensal até o parto","Raio-X mensal","Nenhum exame","Ultrassom a cada semana"],"explicacao":"A queda dos títulos indica resposta ao tratamento."},{"id":4971,"materia":"enf","nivel":1,"enunciado":"O curativo de cateter venoso central é feito com técnica:","opcoes":["Asséptica","Limpa, sem luvas","Sem higiene das mãos","Qualquer uma, conforme o tempo"],"explicacao":"Previne infecção da corrente sanguínea."},{"id":4972,"materia":"enf","nivel":2,"enunciado":"Em uma unidade, o material contaminado deve seguir o fluxo:","opcoes":["Limpeza, preparo/empacotamento, esterilização e armazenamento","Armazenamento, esterilização, limpeza e só então o preparo do pacote","Esterilização direta, sem limpeza","Uso imediato sem nenhum processamento"],"explicacao":"A limpeza é a etapa mais importante: sem ela, a esterilização falha."},{"id":4973,"materia":"enf","nivel":2,"enunciado":"O indicador biológico, no controle da esterilização, usa:","opcoes":["Esporos de bactérias resistentes para testar se o processo matou os microrganismos","Uma fita que muda de cor apenas do lado de fora do pacote","O cheiro do material","A temperatura da sala"],"explicacao":"É o controle mais confiável da eficácia da esterilização."},{"id":4974,"materia":"enf","nivel":2,"enunciado":"A tuberculose é causada pelo:","opcoes":["Mycobacterium tuberculosis (bacilo de Koch)","Vírus influenza","Plasmodium vivax","Staphylococcus aureus resistente à meticilina"],"explicacao":"Transmitida pelo ar por pessoas com a forma pulmonar."},{"id":4975,"materia":"enf","nivel":2,"enunciado":"Na hipoglicemia, os sintomas incluem:","opcoes":["Suor frio, tremor, fome e confusão","Hálito cetônico, muita sede e muita urina","Febre e tosse","Pele seca e quente com sede"],"explicacao":"Os do segundo item são mais típicos de hiperglicemia grave."},{"id":4976,"materia":"enf","nivel":2,"enunciado":"A raiva humana tem letalidade:","opcoes":["De praticamente 100% após o surgimento dos sintomas","Menor que 1%","De 10%","Zero, se a pessoa beber muita água e descansar"],"explicacao":"Por isso a profilaxia após a exposição é fundamental."},{"id":4977,"materia":"enf","nivel":2,"enunciado":"A cólera provoca:","opcoes":["Diarreia aquosa intensa, com risco de desidratação grave","Tosse seca","Manchas na pele","Dor nas articulações e manchas vermelhas"],"explicacao":"A reposição de líquidos é o principal tratamento."},{"id":4978,"materia":"enf","nivel":2,"enunciado":"A doença de notificação imediata (até 24 horas) inclui, entre outras:","opcoes":["Sarampo","Gripe comum","Resfriado","Conjuntivite leve"],"explicacao":"A notificação rápida permite o bloqueio vacinal."},{"id":4979,"materia":"enf","nivel":2,"enunciado":"Na esquistossomose, a infecção ocorre pelo contato com:","opcoes":["Água doce contaminada com larvas (cercárias)","Ar de ambientes fechados e mal ventilados","Picada de barbeiro","Carne de porco"],"explicacao":"O caramujo é o hospedeiro intermediário."},{"id":4980,"materia":"enf","nivel":2,"enunciado":"Na leptospirose, a transmissão ocorre principalmente por contato com:","opcoes":["Água ou lama contaminada com urina de ratos","Picada de pernilongo comum durante a noite","Gotículas de tosse","Alimentos com glúten"],"explicacao":"Comum após enchentes."},{"id":4981,"materia":"enf","nivel":3,"enunciado":"Em paciente com sonda nasoenteral, antes de administrar a dieta ou medicamentos, deve-se:","opcoes":["Confirmar o posicionamento da sonda, conforme protocolo","Aumentar a velocidade da dieta para compensar atrasos","Deitar o paciente reto","Retirar a fixação"],"explicacao":"Após medicamentos, lava-se a sonda com água."},{"id":4982,"materia":"enf","nivel":3,"enunciado":"Comprimidos de liberação prolongada não devem ser triturados porque:","opcoes":["Isso libera a dose de uma vez, com risco de intoxicação","Ficam mais doces","Perdem a cor","Não fazem diferença, pois o efeito é sempre o mesmo"],"explicacao":"Converse com o farmacêutico sobre alternativas."},{"id":4983,"materia":"enf","nivel":3,"enunciado":"O hormônio antidiurético (ADH) atua principalmente:","opcoes":["Nos rins, reduzindo a eliminação de água","No estômago, aumentando a fome e a produção de suco gástrico","Nos ossos, liberando cálcio","Na pele, produzindo suor"],"explicacao":"Produzido no hipotálamo e liberado pela hipófise."},{"id":4984,"materia":"enf","nivel":3,"enunciado":"A administração de medicamento por via intramuscular no deltoide deve respeitar, em adultos, volume máximo de cerca de:","opcoes":["2 mL","10 mL","20 mL","50 mL"],"explicacao":"Músculos maiores, como o ventroglúteo, comportam volumes maiores."},{"id":4985,"materia":"enf","nivel":4,"enunciado":"Em uma sala com paciente com varicela, além da máscara N95/PFF2, devem ser observadas também precauções de:","opcoes":["Contato","Nenhuma outra","Apenas gotículas","Somente padrão, sem máscara"],"explicacao":"A varicela exige precauções por aerossóis e contato."},{"id":4986,"materia":"enf","nivel":4,"enunciado":"Uma solução de clorexidina a 2% contém, em 100 mL:","opcoes":["2 g de clorexidina","20 g","0,2 g","200 mg de clorexidina em cada mililitro"],"explicacao":"Concentração percentual = gramas em 100 mL."},{"id":4987,"materia":"enf","nivel":4,"enunciado":"A diferença entre infecção endógena e exógena é que a endógena:","opcoes":["É causada pela própria flora do paciente","Vem sempre de outro paciente","É transmitida pelos profissionais","É causada por objetos e superfícies contaminados no hospital"],"explicacao":"Ex.: infecção de ferida por bactérias da pele do próprio paciente."},{"id":4988,"materia":"enf","nivel":4,"enunciado":"O controle químico da esterilização usa:","opcoes":["Indicadores que mudam de cor ao serem expostos às condições do processo","Esporos vivos de bactérias resistentes ao calor","Um termômetro de mercúrio","O olfato do profissional"],"explicacao":"Integradores químicos ajudam a monitorar cada pacote; o biológico confirma a eficácia."},{"id":4989,"materia":"sus","nivel":0,"enunciado":"Pela Lei nº 8.080/1990, o SUS é formado pelo conjunto de ações e serviços de saúde prestados por:","opcoes":["Órgãos e instituições públicas federais, estaduais e municipais","Apenas hospitais particulares conveniados aos planos de saúde","Somente o Ministério da Saúde","Cooperativas médicas"],"explicacao":"A iniciativa privada participa de forma complementar."},{"id":4990,"materia":"sus","nivel":0,"enunciado":"O Disque Saúde, canal da Ouvidoria do SUS, é o número:","opcoes":["136","190","100","180"],"explicacao":"180 é a Central de Atendimento à Mulher."},{"id":4991,"materia":"sus","nivel":0,"enunciado":"Os CEREST são centros de referência em:","opcoes":["Saúde do trabalhador","Saúde bucal","Vacinação","Doenças raras e genéticas"],"explicacao":"Fazem parte da RENAST."},{"id":4992,"materia":"sus","nivel":0,"enunciado":"A busca ativa de sintomáticos respiratórios, para a tuberculose, considera na população geral a pessoa com tosse há:","opcoes":["3 semanas ou mais","1 dia","6 meses, sem melhora","1 hora"],"explicacao":"Em populações vulneráveis, qualquer tempo de tosse."},{"id":4993,"materia":"sus","nivel":0,"enunciado":"Na hanseníase, além de tratar o caso, é preciso:","opcoes":["Examinar os contatos do paciente","Isolar a família inteira","Proibir o paciente de trabalhar e de sair de casa até a cura","Queimar as roupas do paciente"],"explicacao":"O exame de contatos ajuda a descobrir casos precocemente."},{"id":4994,"materia":"sus","nivel":0,"enunciado":"Entre as metas internacionais de segurança do paciente está:","opcoes":["Identificar corretamente o paciente","Atender o mais rápido possível, sem conferir dados","Usar sempre o mesmo leito","Evitar falar com o paciente"],"explicacao":"Também comunicação efetiva, cirurgia segura, higiene das mãos e prevenção de quedas e lesões."},{"id":4995,"materia":"sus","nivel":0,"enunciado":"A Política Nacional de Educação Popular em Saúde valoriza:","opcoes":["O diálogo e os saberes populares na construção do cuidado","Apenas o saber dos especialistas","Palestras técnicas sem participação nem perguntas da comunidade","A proibição de práticas tradicionais"],"explicacao":"Instituída em 2013."},{"id":4996,"materia":"sus","nivel":1,"enunciado":"A RDC Anvisa nº 36/2013 determina que os serviços de saúde tenham:","opcoes":["Núcleo de Segurança do Paciente","Plano de saúde próprio","Farmácia de manipulação própria","Heliponto"],"explicacao":"O núcleo promove ações para a segurança do paciente."},{"id":4997,"materia":"sus","nivel":1,"enunciado":"Evento adverso, em segurança do paciente, é:","opcoes":["Um incidente que resultou em dano ao paciente","Qualquer atendimento demorado na recepção da unidade","Uma consulta cancelada","Uma reclamação na ouvidoria"],"explicacao":"O incidente que não chega ao paciente é o 'quase erro'; o que chega sem causar dano é o 'incidente sem dano'."},{"id":4998,"materia":"sus","nivel":1,"enunciado":"A Política Nacional de Vigilância em Saúde foi instituída pelo:","opcoes":["Conselho Nacional de Saúde (Resolução nº 588/2018)","Código Penal","Ministério da Educação","Senado Federal, por meio de lei complementar"],"explicacao":"Abrange vigilância epidemiológica, sanitária, ambiental e do trabalhador."},{"id":4999,"materia":"sus","nivel":1,"enunciado":"Doenças tropicais negligenciadas, como hanseníase e leishmaniose, estão associadas principalmente a:","opcoes":["Pobreza e más condições de vida","Excesso de exercício físico e alimentação rica em proteínas","Alimentação muito saudável","Clima frio"],"explicacao":"Recebem pouco investimento em pesquisa."},{"id":5000,"materia":"sus","nivel":1,"enunciado":"A vacinação contra influenza no SUS é oferecida anualmente, com prioridade para:","opcoes":["Grupos prioritários, como idosos, gestantes, crianças pequenas e profissionais de saúde","Apenas jovens atletas e militares em serviço ativo","Somente turistas","Ninguém, pois é paga"],"explicacao":"O vírus muda, por isso a vacina é atualizada todo ano."},{"id":5001,"materia":"sus","nivel":2,"enunciado":"A Constituição Federal (art. 200) atribui ao SUS, entre outras competências:","opcoes":["Executar ações de vigilância sanitária e epidemiológica e de saúde do trabalhador","Julgar crimes contra a saúde pública e aplicar penas de prisão","Arrecadar impostos de renda","Comandar as Forças Armadas"],"explicacao":"Também participar da formulação da política de saneamento básico."},{"id":5002,"materia":"sus","nivel":2,"enunciado":"Segundo a Constituição, é vedada a destinação de recursos públicos para:","opcoes":["Auxílios ou subvenções às instituições privadas com fins lucrativos","Hospitais públicos","Vacinas","Unidades básicas de saúde e hospitais públicos municipais"],"explicacao":"Art. 199, § 2º."},{"id":5003,"materia":"sus","nivel":2,"enunciado":"A participação direta ou indireta de empresas ou capitais estrangeiros na assistência à saúde no país, pela Constituição:","opcoes":["É vedada, salvo nos casos previstos em lei","É livre e sem limites","É obrigatória","Só é permitida em hospitais públicos federais e universitários"],"explicacao":"Art. 199, § 3º. Leis posteriores ampliaram as exceções."},{"id":5004,"materia":"sus","nivel":3,"enunciado":"O princípio da preservação da autonomia das pessoas, previsto na Lei nº 8.080/1990, refere-se à:","opcoes":["Defesa de sua integridade física e moral","Liberdade de escolher o salário do servidor","Autonomia financeira dos hospitais","Escolha do município onde pagar impostos"],"explicacao":"Art. 7º, III."},{"id":5005,"materia":"sus","nivel":3,"enunciado":"A Lei nº 8.080/1990 garante às pessoas assistidas o direito à:","opcoes":["Informação sobre sua saúde","Cirurgia estética gratuita em qualquer caso","Escolha do salário do médico","Internação sem indicação"],"explicacao":"Art. 7º, V."},{"id":5006,"materia":"sus","nivel":3,"enunciado":"A Lei nº 8.080/1990 prevê, como princípio, a divulgação de informações quanto:","opcoes":["Ao potencial dos serviços de saúde e sua utilização pelo usuário","Aos salários de cada servidor, por nome e cargo","Aos diagnósticos de pacientes famosos","Às senhas dos sistemas"],"explicacao":"Art. 7º, VI."},{"id":5007,"materia":"sus","nivel":4,"enunciado":"Pela Lei nº 8.080/1990, a utilização da epidemiologia serve para:","opcoes":["Estabelecer prioridades, alocar recursos e orientar programas","Escolher a cor dos uniformes","Definir horário de almoço","Contratar empresas de limpeza e de segurança"],"explicacao":"Art. 7º, VII."},{"id":5008,"materia":"sus","nivel":4,"enunciado":"A Lei nº 8.080/1990 prevê a integração, em nível executivo, das ações de:","opcoes":["Saúde, meio ambiente e saneamento básico","Saúde, turismo e esporte de alto rendimento","Educação física, música e teatro","Transporte aéreo e marítimo apenas"],"explicacao":"Art. 7º, X."},{"id":5009,"materia":"med","nivel":0,"enunciado":"Na sepse, o antibiótico deve ser iniciado, idealmente:","opcoes":["Na primeira hora após o reconhecimento","Depois de 3 dias","Só após o resultado da cultura, que leva alguns dias","Nunca"],"explicacao":"Cada hora de atraso aumenta a mortalidade."},{"id":5010,"materia":"med","nivel":0,"enunciado":"Na diarreia aguda em crianças, além da hidratação, o Ministério da Saúde recomenda:","opcoes":["Suplementação de zinco por 10 a 14 dias","Antibiótico para todas as crianças","Suspender a alimentação","Remédio para parar a diarreia em menores de 1 ano"],"explicacao":"O zinco reduz a duração e a gravidade."},{"id":5011,"materia":"med","nivel":0,"enunciado":"A conjuntivite viral costuma apresentar:","opcoes":["Olho vermelho, lacrimejamento e secreção clara","Perda súbita da visão, sem vermelhidão nem secreção","Pus amarelo abundante, sempre","Dor de dente"],"explicacao":"É muito contagiosa: lavar as mãos é essencial."},{"id":5012,"materia":"med","nivel":0,"enunciado":"O herpes-zóster se caracteriza por:","opcoes":["Vesículas dolorosas em faixa, seguindo um nervo, em um lado do corpo","Manchas espalhadas pelo corpo todo, sem dor nem coceira","Febre alta isolada","Coceira só nos pés"],"explicacao":"É a reativação do vírus da varicela."},{"id":5013,"materia":"med","nivel":0,"enunciado":"O teste rápido para HIV na atenção primária:","opcoes":["Dá resultado em cerca de 30 minutos e deve ser oferecido com aconselhamento","Demora 6 meses","Só pode ser feito em hospital, com internação","Exige internação"],"explicacao":"Resultados reagentes seguem o fluxo de confirmação."},{"id":5014,"materia":"med","nivel":0,"enunciado":"A profilaxia pós-exposição ao HIV (PEP) é tomada por:","opcoes":["28 dias","2 dias","1 ano","Uma dose única"],"explicacao":"Deve começar o quanto antes, até 72 horas após a exposição."},{"id":5015,"materia":"med","nivel":1,"enunciado":"Na dor torácica sugestiva de síndrome coronariana, o eletrocardiograma deve ser feito em até:","opcoes":["10 minutos da chegada","24 horas","1 semana","A próxima consulta agendada no ambulatório"],"explicacao":"Para identificar infarto com supradesnivelamento de ST."},{"id":5016,"materia":"med","nivel":1,"enunciado":"É sinal de alarme na cefaleia:","opcoes":["A pior dor de cabeça da vida, de início súbito","Dor leve que melhora com repouso","Dor que piora com estresse","Dor de cabeça há anos, sempre igual e sem outros sintomas"],"explicacao":"Pode indicar hemorragia subaracnóidea."},{"id":5017,"materia":"med","nivel":1,"enunciado":"A otite média aguda bacteriana, quando há indicação de antibiótico, costuma ser tratada com:","opcoes":["Amoxicilina","Insulina","Aciclovir","Fluconazol em dose única"],"explicacao":"Muitos casos melhoram sozinhos com observação."},{"id":5018,"materia":"med","nivel":1,"enunciado":"A PrEP (profilaxia pré-exposição) ao HIV é indicada para:","opcoes":["Pessoas com maior risco de exposição, antes de contato com o vírus","Pessoas que já vivem com HIV, em vez do tratamento antirretroviral","Todos os recém-nascidos","Apenas idosos"],"explicacao":"Disponível gratuitamente no SUS."},{"id":5019,"materia":"med","nivel":1,"enunciado":"Na declaração de óbito, a causa básica da morte deve ser registrada:","opcoes":["Na última linha preenchida da Parte I","Na Parte II, sempre, junto com as outras doenças","No campo do nome","Em qualquer lugar"],"explicacao":"É a doença que iniciou a cadeia de eventos que levou à morte."},{"id":5020,"materia":"med","nivel":2,"enunciado":"O uso racional de antibióticos é importante porque o uso inadequado:","opcoes":["Favorece a resistência bacteriana","Fortalece o sistema imune e previne gripes","Cura viroses mais rápido","Não tem nenhum efeito"],"explicacao":"Antibióticos não tratam infecções virais."},{"id":5021,"materia":"med","nivel":2,"enunciado":"Uma pessoa com tosse há 3 semanas, febre à tarde, suor noturno e emagrecimento deve ser investigada para:","opcoes":["Tuberculose","Rinite alérgica","Enxaqueca","Gastrite"],"explicacao":"Solicita-se baciloscopia ou teste rápido molecular do escarro."},{"id":5022,"materia":"med","nivel":3,"enunciado":"O teste rápido molecular para tuberculose (TRM-TB) detecta:","opcoes":["O material genético do bacilo e a resistência à rifampicina","Apenas anticorpos produzidos meses depois da infecção","A glicemia","A função dos rins"],"explicacao":"Resultado em cerca de 2 horas."},{"id":5023,"materia":"med","nivel":4,"enunciado":"Na hipertensão resistente, considera-se a pessoa que não atinge a meta mesmo usando:","opcoes":["Três ou mais medicamentos em doses adequadas, incluindo um diurético","Apenas um medicamento, em dose baixa","Nenhum medicamento","Somente chás"],"explicacao":"Antes, é preciso confirmar a adesão e a medida correta da pressão."},{"id":5024,"materia":"fisio","nivel":0,"enunciado":"As LER/DORT estão relacionadas principalmente a:","opcoes":["Movimentos repetitivos e postura inadequada no trabalho","Infecções virais","Alergias alimentares e intolerância à lactose","Excesso de sono"],"explicacao":"A ergonomia ajuda a prevenir."},{"id":5025,"materia":"fisio","nivel":0,"enunciado":"A cinesioterapia é o tratamento por meio de:","opcoes":["Movimento e exercícios terapêuticos","Calor apenas, aplicado com bolsas","Medicamentos","Cirurgia"],"explicacao":"Base de quase todos os programas de reabilitação."},{"id":5026,"materia":"fisio","nivel":0,"enunciado":"Na paralisia facial periférica (de Bell), a fisioterapia usa, entre outros:","opcoes":["Exercícios da mímica facial","Imobilização do rosto","Gesso no pescoço","Repouso absoluto do rosto por meses"],"explicacao":"Também orientar a proteção do olho que não fecha."},{"id":5027,"materia":"fisio","nivel":0,"enunciado":"Na osteoporose, são indicados exercícios:","opcoes":["Com carga e de equilíbrio, para fortalecer ossos e prevenir quedas","Apenas de alongamento passivo, deitado e sem carga","Nenhum, pelo risco de fratura","Somente na piscina, sem carga"],"explicacao":"Sempre adaptados à condição da pessoa."},{"id":5028,"materia":"fisio","nivel":0,"enunciado":"A mobilização precoce em pacientes de UTI ajuda a:","opcoes":["Reduzir a fraqueza muscular e o tempo de internação","Aumentar as complicações e o risco de quedas","Piorar a respiração","Atrasar a alta"],"explicacao":"Quando o paciente está estável."},{"id":5029,"materia":"fisio","nivel":1,"enunciado":"A manobra de Ortolani é usada no recém-nascido para avaliar:","opcoes":["Displasia do desenvolvimento do quadril","Pé torto congênito","Torcicolo congênito","Escoliose idiopática"],"explicacao":"Um 'clique' sugere quadril instável."},{"id":5030,"materia":"fisio","nivel":1,"enunciado":"O método Ponseti é usado no tratamento do:","opcoes":["Pé torto congênito","Joelho valgo","Ombro congelado do adulto","Pé plano adulto"],"explicacao":"Usa gessos seriados e, depois, órtese."},{"id":5031,"materia":"fisio","nivel":1,"enunciado":"O treino dos músculos do assoalho pélvico pode usar o biofeedback para:","opcoes":["Mostrar à pessoa se está contraindo corretamente","Medir a glicemia","Aquecer a região","Substituir a avaliação do fisioterapeuta"],"explicacao":"Muito usado na incontinência urinária."},{"id":5032,"materia":"fisio","nivel":1,"enunciado":"No torcicolo muscular congênito, há encurtamento do músculo:","opcoes":["Esternocleidomastoideo","Bíceps","Quadríceps","Glúteo máximo e piriforme"],"explicacao":"O bebê inclina a cabeça para um lado."},{"id":5033,"materia":"fisio","nivel":2,"enunciado":"A escala de Fugl-Meyer avalia:","opcoes":["O desempenho motor e sensorial após AVC","A dor crônica","A capacidade pulmonar","A espasticidade apenas, nos membros inferiores"],"explicacao":"Muito usada em pesquisas e na reabilitação."},{"id":5034,"materia":"fisio","nivel":2,"enunciado":"Na reabilitação pós-covid, uma queixa comum que exige atenção é:","opcoes":["Fadiga e falta de ar aos esforços","Aumento súbito da força","Melhora imediata do condicionamento","Ausência de qualquer sintoma"],"explicacao":"O programa deve ser progressivo e monitorado."},{"id":5035,"materia":"fisio","nivel":2,"enunciado":"Na atenção primária, o fisioterapeuta das equipes multiprofissionais atua também com:","opcoes":["Grupos de educação em saúde e atividades coletivas","Apenas atendimentos hospitalares","Somente cirurgias","Exclusivamente em academias privadas e clubes esportivos"],"explicacao":"Ex.: grupos de coluna e de idosos."},{"id":5036,"materia":"fisio","nivel":3,"enunciado":"No alongamento estático para ganho de flexibilidade, recomenda-se manter cada posição por cerca de:","opcoes":["15 a 30 segundos","1 a 2 segundos, com movimentos rápidos e balísticos","10 minutos","1 hora"],"explicacao":"Repetido algumas vezes, sem provocar dor intensa."},{"id":5037,"materia":"fisio","nivel":3,"enunciado":"Na tendinopatia, os exercícios excêntricos:","opcoes":["Trabalham o músculo enquanto ele se alonga, estimulando a recuperação do tendão","Devem ser evitados sempre","Envolvem só contrações sem movimento, sem nenhuma carga","Substituem qualquer avaliação"],"explicacao":"Muito usados no tendão de Aquiles e no patelar."},{"id":5038,"materia":"fisio","nivel":4,"enunciado":"A estimulação elétrica para fortalecimento do quadríceps após cirurgia de LCA é usada para:","opcoes":["Reduzir a inibição muscular e ajudar a recuperar a força","Aquecer o joelho","Diagnosticar a lesão","Substituir os exercícios ativos durante toda a reabilitação"],"explicacao":"Associada ao treino ativo."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('sus','enf','fisio','med') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
